<?php endforeach ?>
<?php else: ?><p>Source details are unavailable for this historical finding.</p><?php endif ?>
</details><?php endif ?>
<?php if(!empty($finding['detail']['review_only'])): ?><p class="notice alert alert-info"><?=$escape(!empty($finding['detail']['advisory_kind'])?'Website advisory':'Heuristic match')?> - manual review required. Automatic actions are excluded.</p><?php endif ?><?php if(!empty($finding['detail']['rule_id'])): ?><details><summary class="button cs-disclosure"><i class="fas fa-caret-right cs-disclosure-icon" aria-hidden="true"></i>Rule source</summary><p><?=$escape($finding['detail']['source_id'])?> · <?=$escape($finding['detail']['source_version']??'')?></p><p class="path"><?=$escape($finding['detail']['source_url']??'')?></p><p>License: <?=$escape($finding['detail']['license']??'Unknown')?></p><p class="path">Rule ID: <?=$escape($finding['detail']['rule_id'])?></p><?php if(!empty($finding['detail']['also_matched'])): ?><p><?=count($finding['detail']['also_matched'])?> equivalent rules also matched.</p><?php endif ?></details><?php endif ?></td><td><?=$escape($finding['engine'].' / '.$finding['provider'])?></td><td><?=$escape($finding['status'])?></td><td><?php if($finding['status']==='open' && $finding['site_availability']['available']): ?><?php if(isset($finding['fingerprint']['wordpress']['expected'])): ?><button class="button" data-action="repair-preview" data-finding_id="<?=$escape($finding['id'])?>">Prepare repair preview</button><?php endif ?><details><summary class="button cs-disclosure"><i class="fas fa-caret-right cs-disclosure-icon" aria-hidden="true"></i>Restore from a backup</summary><div class="cs-native-backups" data-finding="<?=$escape($finding['id'])?>"><button type="button" class="button cs-backup-list">List Hestia backups</button><select class="form-select" aria-label="Hestia backup" hidden></select><button type="button" data-capability="repair" class="button cs-backup-prepare" hidden disabled>Prepare Hestia backup preview</button><p role="status"></p></div><p>Choose a backup file inside this website. Review its differences and scan results before replacing the detected file.</p><label>Backup path relative to this website <input class="form-control" id="backup-<?=$escape($finding['id'])?>" placeholder="backups/clean-file.php" maxlength="4096"></label><button class="button" data-action="repair-backup-preview" data-finding_id="<?=$escape($finding['id'])?>" data-path-input="backup-<?=$escape($finding['id'])?>">Prepare backup preview</button></details><?php if(empty($finding['fingerprint']['missing'])): ?><?php if(in_array($finding['engine'],['clamav','yara']) && in_array(strtolower(pathinfo($finding['path'],PATHINFO_EXTENSION)),['php','phtml'])): ?><button class="button" data-action="cleanup-preview" data-finding_id="<?=$escape($finding['id'])?>">Prepare targeted cleaning</button><?php endif ?><button class="button" data-action="quarantine" data-finding_id="<?=$escape($finding['id'])?>">Quarantine</button><button class="button" data-action="exception-add" data-kind="file" data-finding_id="<?=$escape($finding['id'])?>">Trust this content</button><button class="button" data-action="exception-add" data-kind="signature" data-finding_id="<?=$escape($finding['id'])?>">Ignore this rule for this file</button><?php endif ?><?php endif ?></td></tr><?php endforeach ?>
